function normalizeOwnerPrivatePolicyDescription(description: string): string {
  return ownerPrivatePolicyDescriptionRewrites.reduce(
    (current, [outdated, corrected]) => current.replace(outdated, corrected),
    description,
  );
}

/** Browser operations are exposed only through the E2B-backed CHUCK_BROWSER tools. */
export function canonicalNativeToolSlug(name: string): string {
  return name;
}

export const chuckTools = [...baseChuckTools, ...shoppingAndBrowserTools, ...toolReliabilityTools]
  .map((tool) => {
  const name = canonicalNativeToolSlug(tool.function.name);
  const description = normalizeOwnerPrivatePolicyDescription(tool.function.description);
  const parameters: any = tool.function.parameters && typeof tool.function.parameters === "object"
    ? { ...tool.function.parameters, properties: { ...tool.function.parameters.properties } }
    : tool.function.parameters;
  if (name === "CHUCK_DAYTONA_COMPUTER" && parameters?.properties?.processName?.enum) {
    parameters.properties.processName = {
      ...parameters.properties.processName,
      enum: parameters.properties.processName.enum.filter((value: string) => value !== "browser" && value !== "chrome"),
    };
  }
  return { ...tool, function: { ...tool.function, name, description, parameters } };
  });

// Kept in the native catalog for existing SDK/API clients and resumed runs,
// but image transfer is now resolved transparently at Composio dispatch.
export const modelFacingChuckTools = chuckTools.filter((tool) => tool.function.name !== "CHUCK_MEDIA_BRIDGE");

// Formula cells are explicit, bounded per-sheet inputs. The Daytona boundary
// validates them again and LibreOffice independently recalculates them before
// the artifact is registered.
