spreadsheetToolSchema.function.description += " Formula cells may be supplied per sheet as formulas [{cell,formula,expectedValue?}]. Only basic arithmetic and the documented safe functions are accepted; expectedValue is checked against a fresh LibreOffice calculation. Returned verification evidence reports extracted content and formula counts; it is not a substitute for reviewing business assumptions.";
spreadsheetToolSchema.function.parameters.properties.sheets.items.properties = {
  name: { type: "string" },
  rows: { description: "Cell matrix or {headers,rows}; use numeric/boolean cells for calculations. Formula cells are applied separately after the table is written." },
  formulas: { type: "array", items: { type: "object", properties: { cell: { type: "string", description: "Cell address such as C4" }, formula: { type: "string", description: "Safe formula such as SUM(B4:B8), optionally with a leading =" }, expectedValue: { type: ["string", "number", "boolean"], description: "Optional expected result checked independently after recalculation" } }, required: ["cell", "formula"] } },
  tabColor: { type: "string", description: "Optional six-digit hex color" },
};
const documentToolSchema = chuckTools.find((item) => item.function.name === "CHUCK_CREATE_DOCUMENT") as any;
documentToolSchema.function.description += " Before registration, Chusky independently extracts the rendered text, checks that it contains the requested title, and renders every page; returned evidence gives page and extracted-text counts, not human editorial approval.";
const pdfToolSchema = chuckTools.find((item) => item.function.name === "CHUCK_CREATE_PDF") as any;
pdfToolSchema.function.description += " Before registration, Chusky independently extracts the rendered text, checks that it contains the requested title, and renders every page; returned evidence gives page and extracted-text counts, not human editorial approval.";
const missionStartToolSchema = chuckTools.find((item) => item.function.name === "CHUCK_MISSION_START") as any;
Object.assign(missionStartToolSchema.function.parameters.properties, {
  durationMode: { type: "string", enum: ["active", "wall_clock"], description: "Defaults to active execution time; waits, pauses, blockers, and scheduling gaps do not consume it. wall_clock preserves the original elapsed-time contract." },
  maxLifetimeSeconds: { type: "integer", minimum: 60, maximum: 2592000, description: "Absolute lifetime from mission start including waits. Defaults to 14 days; cannot be extended automatically." },
  automaticExtensionSeconds: { type: "integer", minimum: 0, maximum: 3600, description: "Owner-approved seconds per automatic execution-time extension. Set together with maxAutomaticExtensions only when the owner authorizes this allowance. Default zero." },
  maxAutomaticExtensions: { type: "integer", minimum: 0, maximum: 10, description: "Owner-approved extension count. Requires new trusted completed-step progress for every extension; does not raise spend, tool calls, or steps." },
  budgetCeiling: { type: "object", additionalProperties: false, description: "Owner-approved upper bounds that the worker may adjust without another approval.", properties: { maxDurationSeconds: { type: "integer", minimum: 60, maximum: 2592000 }, maxSteps: { type: "integer", minimum: 1, maximum: 1000 }, maxSlices: { type: "integer", minimum: 1, maximum: 100000 }, maxToolCalls: { type: "integer", minimum: 1, maximum: 10000 }, maxCost: { type: "number", minimum: 0, maximum: 10000 } } },
});
missionStartToolSchema.function.description = "Create a NEW durable autonomous mission; this tool never resumes an existing mission. For existing mission IDs, call CHUCK_MISSION_RESUME with {id}. Do not pass id to this create tool. Use bounded steps, a concrete definition of done, and evidence criteria for strict verification. In step allowedTools, list only executable provider/native tools; omit CHUCK_MISSION_*, CHUCK_TASK_*, COMPOSIO_EXECUTE_TOOL, and COMPOSIO_MULTI_EXECUTE_TOOL because lifecycle controls are supervisor-owned and added automatically. Independent steps may run in parallel.";
const missionResumeToolSchema = chuckTools.find((item) => item.function.name === "CHUCK_MISSION_RESUME") as any;
missionResumeToolSchema.function.parameters.properties.maxDurationSeconds.description = "Optional exact-owner-approved increase to the existing duration cap: active execution seconds for new missions, total wall-clock seconds from original start for legacy missions. Never reset usage or raise it autonomously outside the recorded extension allowance.";
missionResumeToolSchema.function.description = "Resume an EXISTING mission owned by this user, using its id, when paused, blocked, or failed. Repeating this for an already-running mission safely repairs missing deterministic task scheduling without duplicate work. This tool never creates a mission. For a new mission, call CHUCK_MISSION_START with title, objective, and definitionOfDone. Waiting approvals still require their exact persisted approval; never infer approval from chat.";
const taskCreateToolSchema = chuckTools.find((item) => item.function.name === "CHUCK_TASK_CREATE") as any;
taskCreateToolSchema.function.description = "Create a NEW durable task; this tool does not resume an existing task. To inspect an existing task, use CHUCK_TASK_GET with its id, then choose the lifecycle action appropriate to its status. Repeating the same create request in one agent run is idempotent.";

/** Validate local-tool arguments at the execution boundary, not just in the model prompt. */
export function validateNativeToolArguments(name: string, args: Record<string, unknown>): void {
  const canonicalName = canonicalNativeToolSlug(name);
  const tool = chuckTools.find((item) => item.function.name === canonicalName);
  if (!tool) throw new Error(`Unknown native tool: ${name}`);
  if (!args || typeof args !== "object" || Array.isArray(args)) throw new Error(`${name} arguments must be an object`);
  if (canonicalName === "CHUCK_MISSION_START" && Object.hasOwn(args, "id")) {
    throw new Error("CHUCK_MISSION_START creates a new mission and does not accept an existing mission ID. To continue an existing mission, call CHUCK_MISSION_RESUME with {id}. No mission was created.");
  }
  if (canonicalName === "CHUCK_TASK_CREATE" && Object.hasOwn(args, "id")) {
    throw new Error("CHUCK_TASK_CREATE creates a new task and does not accept an existing task ID. Call CHUCK_TASK_GET to inspect it, then use the lifecycle action appropriate to its status. No task was created.");
  }
  const schema = tool.function.parameters as JsonSchema;
  // A Python payload plus an existing interpreter context unambiguously means
  // "run". Keep create/list/delete explicit because they have different effects.
  if (canonicalName === "CHUCK_DAYTONA_CODE" && args.action === undefined && typeof args.code === "string" && args.code.trim() && typeof args.contextId === "string" && args.contextId.trim()) {
    args.action = "run";
  }
  // Models occasionally serialize structured arguments as JSON text, or emit
  // one PDF section instead of a one-item array. Normalize only these safe
  // structural forms before enforcing the schema so a recoverable formatting
  // mistake does not abort an otherwise valid document request.
  for (const [key, rule] of Object.entries(schema.properties ?? {})) {
    if (rule.type !== "array") continue;
    const value = args[key];
    if (typeof value === "string") {
      try {
        const parsed = JSON.parse(value);
        if (Array.isArray(parsed)) args[key] = parsed;
      } catch {
        // The normal type error below remains actionable for non-JSON text.
      }
    } else if (canonicalName === "CHUCK_CREATE_PDF" && key === "sections" && value && typeof value === "object" && !Array.isArray(value)) {
      args[key] = [value];
    }
  }
  validateToolArgumentsAgainstSchema(canonicalName, args, schema);
}

/** Validate provider-generated arguments against the exact advertised schema. */
export function validateToolArgumentsAgainstSchema(name: string, args: Record<string, unknown>, inputSchema: unknown, maxBytes = 1_048_576): void {
  if (!args || typeof args !== "object" || Array.isArray(args)) throw new Error(`${name} arguments must be an object`);
  let serialized: string;
  try { serialized = JSON.stringify(args); } catch { throw new Error(`${name} arguments are not valid JSON data`); }
  if (!Number.isSafeInteger(maxBytes) || maxBytes < 1 || maxBytes > 40 * 1024 * 1024) throw new Error("Invalid internal argument validation limit");
  if (Buffer.byteLength(serialized, "utf8") > maxBytes) throw new Error(`${name} arguments exceed the ${maxBytes}-byte limit`);
  if (!inputSchema || typeof inputSchema !== "object" || Array.isArray(inputSchema)) throw new Error(`${name} has an invalid argument schema`);
  const errors: string[] = [];
  validateJsonSchema(args, inputSchema as JsonSchema, "", name, errors, { nodes: 0 });
  if (errors.length) throw new Error(errors[0]);
}

type JsonSchema = {
  type?: string | readonly string[];
  enum?: readonly unknown[];
  required?: readonly string[];
  properties?: Record<string, JsonSchema>;
  items?: JsonSchema;
  additionalProperties?: boolean | JsonSchema;
  minimum?: number;
  maximum?: number;
  minLength?: number;
  maxLength?: number;
  minItems?: number;
  maxItems?: number;
  minProperties?: number;
  maxProperties?: number;
  pattern?: string;
};

function jsonSchemaTypeMatches(value: unknown, type: string): boolean {
  switch (type) {
    case "null": return value === null;
    case "object": return typeof value === "object" && value !== null && !Array.isArray(value);
    case "array": return Array.isArray(value);
    case "integer": return typeof value === "number" && Number.isFinite(value) && Number.isInteger(value);
    case "number": return typeof value === "number" && Number.isFinite(value);
    case "string": return typeof value === "string";
    case "boolean": return typeof value === "boolean";
    default: return false;
  }
}

function validateJsonSchema(value: unknown, schema: JsonSchema, path: string, toolName: string, errors: string[], budget: { nodes: number }, depth = 0): void {
  budget.nodes += 1;
  if (depth > 64) throw new Error(`${toolName} arguments exceed the maximum nesting depth of 64`);
  if (budget.nodes > 25_000) throw new Error(`${toolName} arguments exceed the maximum of 25000 validated values`);
  const displayPath = path ? `${toolName}${path.startsWith("[") ? "" : "."}${path}` : toolName;
  const types = schema.type === undefined ? [] : Array.isArray(schema.type) ? schema.type : [schema.type];
  if (types.length && !types.some((type) => jsonSchemaTypeMatches(value, type))) {
    errors.push(`${displayPath} must be ${types.join(" or ")}`);
    return;
  }
  if (schema.enum && !schema.enum.some((allowed) => Object.is(allowed, value))) {
    errors.push(`${displayPath} has an unsupported value`);
    return;
  }
  if (typeof value === "number") {
    if (schema.minimum !== undefined && value < schema.minimum) errors.push(`${displayPath} must be at least ${schema.minimum}`);
    if (schema.maximum !== undefined && value > schema.maximum) errors.push(`${displayPath} must be at most ${schema.maximum}`);
  }
  if (typeof value === "string") {
    if (schema.minLength !== undefined && value.length < schema.minLength) errors.push(`${displayPath} must have at least ${schema.minLength} characters`);
    if (schema.maxLength !== undefined && value.length > schema.maxLength) errors.push(`${displayPath} exceeds maxLength ${schema.maxLength}`);
    if (schema.pattern !== undefined) {
      let matches = false;
      try { matches = new RegExp(schema.pattern).test(value); } catch { errors.push(`${toolName} has an invalid schema pattern at ${path}`); return; }
      if (!matches) errors.push(`${displayPath} does not match the required pattern`);
    }
  }
  if (Array.isArray(value)) {
    if (schema.minItems !== undefined && value.length < schema.minItems) errors.push(`${displayPath} must contain at least ${schema.minItems} items (minItems)`);
    if (schema.maxItems !== undefined && value.length > schema.maxItems) errors.push(`${displayPath} exceeds maxItems ${schema.maxItems}`);
    if (schema.items) value.forEach((item, index) => validateJsonSchema(item, schema.items!, `${path}[${index}]`, toolName, errors, budget, depth + 1));
  }
  if (value !== null && typeof value === "object" && !Array.isArray(value)) {
    const object = value as Record<string, unknown>;
    const keys = Object.keys(object);
    if (keys.length > 25_000) throw new Error(`${toolName} arguments exceed the maximum of 25000 object properties`);
    if (schema.minProperties !== undefined && keys.length < schema.minProperties) errors.push(`${displayPath} must contain at least ${schema.minProperties} properties`);
    if (schema.maxProperties !== undefined && keys.length > schema.maxProperties) errors.push(`${displayPath} exceeds maxProperties ${schema.maxProperties}`);
    for (const required of schema.required ?? []) {
      if (!(required in object) || object[required] === undefined || object[required] === null || (typeof object[required] === "string" && !object[required].trim())) {
        errors.push(`${displayPath} requires argument: ${required}`);
      }
    }
    for (const [key, child] of Object.entries(object)) {
      const childSchema = schema.properties?.[key];
      const childPath = path ? `${path}.${key}` : key;
      if (childSchema) validateJsonSchema(child, childSchema, childPath, toolName, errors, budget, depth + 1);
      else if (schema.additionalProperties === false) errors.push(`${toolName}.${childPath} is not allowed`);
      else if (schema.additionalProperties && typeof schema.additionalProperties === "object") validateJsonSchema(child, schema.additionalProperties, childPath, toolName, errors, budget, depth + 1);
    }
  }
}
